<?php
 enum StatusEnum: int { case PENDING = 1; case IN_PROGRESS = 2; case SUCCESSED = 3; case FAILED = 4; case CANCELLED = 5; public function label(): string { return self::getLabel($this); } public function name(): string { return implode(array_map(fn($item): string => ucfirst(strtolower($item)), explode('_', $this->name))); } public static function fromString(string $value): StatusEnum { foreach (StatusEnum::cases() as $enum) { if ($enum->name() === $value) { return $enum; } } throw new Exception("Перечисление '$value' не найдено"); } private static function getLabel(self $value): string { return match ($value) { self::PENDING => 'В ожидании', self::IN_PROGRESS => 'В процессе обработки', self::SUCCESSED => 'Успешно', self::FAILED => 'Ошибка', self::CANCELLED => 'Отменен', }; } } enum HistoryTypeEnum: int { case PATIENT = 1; case ENCOUNTER = 2; public function label(): string { return self::getLabel($this); } private static function getLabel(self $value): string { return match ($value) { self::PATIENT => 'Действие с пациентом', self::ENCOUNTER => 'Действие с осмотром', }; } } enum HistoryActionTypeEnum: int { case REGISTRATION = 1; case CHECK_STATUS = 2; case CANCEL = 3; public function label(): string { return self::getLabel($this); } private static function getLabel(self $value): string { return match ($value) { self::REGISTRATION => 'Регистрация', self::CHECK_STATUS => 'Проверка статуса', self::CANCEL => 'Отмена', }; } } 